+// Match a frame sequence at position `at`.
+function matchAt(groups: string[], at: number, seq: string[]): boolean {
+  if (at + seq.length > groups.length) return false;
+  for (let j = 0; j < seq.length; j++) if (groups[at + j] !== seq[j]) return false;
+  return true;
